bounded_host_request.command:
set -eu
test "$(git rev-parse HEAD)" = "4b06a39ebdb8a99d5544b27c8a52f33ad8e42440"
docker exec -i -w /app debug-ai-debug-ai-1 node - <<'NODE'
const fs=require("node:fs"),path=require("node:path"),cp=require("node:child_process");
const {RepoPolicy}=require("./server/repo-policy.js"),{repositorySnapshotId}=require("./server/control/repository-snapshot.js");
const p=new RepoPolicy(),repo=p.assertRepo("/workspace/debug-ai");
console.log("REPO_POLICY=PASS");
const g=cp.spawnSync("git",["-C",repo,"rev-parse","HEAD"],{encoding:"utf8",timeout:10000});
console.log("GIT_STATUS="+JSON.stringify({code:g.status,error:g.error?.code||null,unsafe_owner:/dubious ownership/i.test(g.stderr||"")}));
try{console.log("SNAPSHOT_KIND="+repositorySnapshotId(repo,{allowMissingGitMarker:true}).split("_")[0]);}catch(e){
 const cause=e.cause||{},raw=String(cause.message||"");
 const file=typeof cause.path==="string"?path.relative(repo,cause.path):null;
 const parts=file?file.split(path.sep):[];
 console.log("SNAPSHOT_ERROR="+JSON.stringify({code:e.message,cause_code:cause.code||null,cause_kind:raw.split(":")[0].slice(0,120),path_kind:parts.some(x=>x===".env"||x.startsWith(".env.")||/secret|credential|token|\.key$/i.test(x))?"PROTECTED_CONFIG":file?parts[0]:"NONE",is_git_metadata:parts.includes(".git"),git_cause:e.git_cause?.code||null}));
 process.exitCode=4;
}
NODE
